(() => {
  const roundUpToHalfKg = (weightKg) => {
    const doubled = weightKg * 2;
    const nearest = Math.round(doubled);
    if (Math.abs(doubled - nearest) < 1e-9) {
      return nearest / 2;
    }
    return Math.ceil(doubled) / 2;
  };
  const billableWeight = (input) => {
    const { lengthCm, widthCm, heightCm, actualWeightKg } = input;
    const dimensionalWeightKg = lengthCm * widthCm * heightCm / 5e3;
    const roundedDimensionalWeightKg = roundUpToHalfKg(dimensionalWeightKg);
    const roundedActualWeightKg = roundUpToHalfKg(actualWeightKg);
    const billableWeightKg = Math.max(roundedDimensionalWeightKg, roundedActualWeightKg);
    return { dimensionalWeightKg, roundedDimensionalWeightKg, roundedActualWeightKg, billableWeightKg };
  };
  return { billableWeight, roundUpToHalfKg };
})()

