build.unitScript:
test("AC-1: 40 x 30 x 20 cm parcel at 3.2 kg bills 5.0 kg from the rounded dimensional weight", () => {
  assert.deepEqual(code.billableWeight({ lengthCm: 40, widthCm: 30, heightCm: 20, actualWeightKg: 3.2 }), { dimensionalWeightKg: 4.8, roundedDimensionalWeightKg: 5, roundedActualWeightKg: 3.5, billableWeightKg: 5 });
});
test("AC-2: 10 x 10 x 10 cm parcel at 2.0 kg bills 2.0 kg from the actual weight", () => {
  assert.deepEqual(code.billableWeight({ lengthCm: 10, widthCm: 10, heightCm: 10, actualWeightKg: 2 }), { dimensionalWeightKg: 0.2, roundedDimensionalWeightKg: 0.5, roundedActualWeightKg: 2, billableWeightKg: 2 });
});
test("AC-3: billable weight uses the rounded values, so it is 5.0 and not the raw 4.8", () => {
  const r = code.billableWeight({ lengthCm: 40, widthCm: 30, heightCm: 20, actualWeightKg: 3.2 });
  assert.equal(r.billableWeightKg, Math.max(r.roundedDimensionalWeightKg, r.roundedActualWeightKg));
  assert.ok(r.billableWeightKg !== r.dimensionalWeightKg);
  assert.equal(r.billableWeightKg, 5);
});
test("rounding goes up to the next 0.5 kg even for small excesses", () => {
  assert.equal(code.roundUpToHalfKg(3.2), 3.5);
  assert.equal(code.roundUpToHalfKg(4.01), 4.5);
  assert.equal(code.roundUpToHalfKg(0.2), 0.5);
  assert.equal(code.roundUpToHalfKg(4.6), 5);
});
test("values already a multiple of 0.5 kg stay unchanged when rounded", () => {
  assert.equal(code.roundUpToHalfKg(2), 2);
  assert.equal(code.roundUpToHalfKg(0.5), 0.5);
  assert.equal(code.roundUpToHalfKg(5), 5);
  assert.equal(code.roundUpToHalfKg(3.5), 3.5);
});
test("a heavy small parcel bills its rounded actual weight", () => {
  const r = code.billableWeight({ lengthCm: 10, widthCm: 10, heightCm: 10, actualWeightKg: 7.1 });
  assert.equal(r.roundedActualWeightKg, 7.5);
  assert.equal(r.billableWeightKg, 7.5);
});

build.testScript:
test("billable weight for a 40 by 30 by 20 cm parcel at 3.2 kg is 5.0 kg", function() {
  var result = code.billableWeight({ lengthCm: 40, widthCm: 30, heightCm: 20, actualWeightKg: 3.2 });
  assert.deepEqual(result, { dimensionalWeightKg: 4.8, roundedDimensionalWeightKg: 5, roundedActualWeightKg: 3.5, billableWeightKg: 5 });
});
test("billable weight for a 10 by 10 by 10 cm parcel at 2.0 kg is 2.0 kg", function() {
  var result = code.billableWeight({ lengthCm: 10, widthCm: 10, heightCm: 10, actualWeightKg: 2 });
  assert.deepEqual(result, { dimensionalWeightKg: 0.2, roundedDimensionalWeightKg: 0.5, roundedActualWeightKg: 2, billableWeightKg: 2 });
});
test("rounded weights are compared not raw weights", function() {
  var result = code.billableWeight({ lengthCm: 20, widthCm: 20, heightCm: 20, actualWeightKg: 1.2 });
  assert.deepEqual(result, { dimensionalWeightKg: 1.6, roundedDimensionalWeightKg: 2, roundedActualWeightKg: 1.5, billableWeightKg: 2 });
});
test("rounded actual weight greater than exact dimensional weight is billed", function() {
  var result = code.billableWeight({ lengthCm: 30, widthCm: 25, heightCm: 10, actualWeightKg: 1.6 });
  assert.deepEqual(result, { dimensionalWeightKg: 1.5, roundedDimensionalWeightKg: 1.5, roundedActualWeightKg: 2, billableWeightKg: 2 });
});
test("a tie after both weights round up bills that shared rounded weight", function() {
  var result = code.billableWeight({ lengthCm: 22, widthCm: 25, heightCm: 10, actualWeightKg: 1.2 });
  assert.deepEqual(result, { dimensionalWeightKg: 1.1, roundedDimensionalWeightKg: 1.5, roundedActualWeightKg: 1.5, billableWeightKg: 1.5 });
});
test("exact multiples of 0.5 stay unchanged and the actual weight wins", function() {
  var result = code.billableWeight({ lengthCm: 20, widthCm: 25, heightCm: 10, actualWeightKg: 2.5 });
  assert.deepEqual(result, { dimensionalWeightKg: 1, roundedDimensionalWeightKg: 1, roundedActualWeightKg: 2.5, billableWeightKg: 2.5 });
});
test("dimensional weight is length times width times height divided by 5000", function() {
  var result = code.billableWeight({ lengthCm: 30, widthCm: 25, heightCm: 20, actualWeightKg: 1 });
  assert.deepEqual(result, { dimensionalWeightKg: 3, roundedDimensionalWeightKg: 3, roundedActualWeightKg: 1, billableWeightKg: 3 });
});
test("equal rounded weights bill that value", function() {
  var result = code.billableWeight({ lengthCm: 40, widthCm: 25, heightCm: 10, actualWeightKg: 2 });
  assert.deepEqual(result, { dimensionalWeightKg: 2, roundedDimensionalWeightKg: 2, roundedActualWeightKg: 2, billableWeightKg: 2 });
});
test("zero actual weight stays 0 and a 1 cm cube rounds dimensional weight up to 0.5", function() {
  var result = code.billableWeight({ lengthCm: 1, widthCm: 1, heightCm: 1, actualWeightKg: 0 });
  assert.deepEqual(result, { dimensionalWeightKg: 2e-4, roundedDimensionalWeightKg: 0.5, roundedActualWeightKg: 0, billableWeightKg: 0.5 });
});
test("zero length gives dimensional weight 0 and actual 0.1 rounds up to 0.5", function() {
  var result = code.billableWeight({ lengthCm: 0, widthCm: 30, heightCm: 20, actualWeightKg: 0.1 });
  assert.deepEqual(result, { dimensionalWeightKg: 0, roundedDimensionalWeightKg: 0, roundedActualWeightKg: 0.5, billableWeightKg: 0.5 });
});
test("actual weight exactly 0.5 stays 0.5 and is not raised to 1.0", function() {
  var result = code.billableWeight({ lengthCm: 10, widthCm: 10, heightCm: 5, actualWeightKg: 0.5 });
  assert.deepEqual(result, { dimensionalWeightKg: 0.1, roundedDimensionalWeightKg: 0.5, roundedActualWeightKg: 0.5, billableWeightKg: 0.5 });
});
test("actual weight 0.6 one step above 0.5 rounds to 1.0", function() {
  var result = code.billableWeight({ lengthCm: 25, widthCm: 10, heightCm: 10, actualWeightKg: 0.6 });
  assert.deepEqual(result, { dimensionalWeightKg: 0.5, roundedDimensionalWeightKg: 0.5, roundedActualWeightKg: 1, billableWeightKg: 1 });
});
test("actual weight exactly 1.0 stays 1.0 and wins", function() {
  var result = code.billableWeight({ lengthCm: 25, widthCm: 10, heightCm: 10, actualWeightKg: 1 });
  assert.deepEqual(result, { dimensionalWeightKg: 0.5, roundedDimensionalWeightKg: 0.5, roundedActualWeightKg: 1, billableWeightKg: 1 });
});
test("actual weight 1.1 one step above 1.0 rounds to 1.5", function() {
  var result = code.billableWeight({ lengthCm: 20, widthCm: 25, heightCm: 10, actualWeightKg: 1.1 });
  assert.deepEqual(result, { dimensionalWeightKg: 1, roundedDimensionalWeightKg: 1, roundedActualWeightKg: 1.5, billableWeightKg: 1.5 });
});
test("dimensional weight 2.1 rounds up to 2.5 and not to 2.0", function() {
  var result = code.billableWeight({ lengthCm: 42, widthCm: 25, heightCm: 10, actualWeightKg: 2 });
  assert.deepEqual(result, { dimensionalWeightKg: 2.1, roundedDimensionalWeightKg: 2.5, roundedActualWeightKg: 2, billableWeightKg: 2.5 });
});
test("both weights round up and the rounded actual weight wins", function() {
  var result = code.billableWeight({ lengthCm: 31, widthCm: 25, heightCm: 20, actualWeightKg: 3.6 });
  assert.deepEqual(result, { dimensionalWeightKg: 3.1, roundedDimensionalWeightKg: 3.5, roundedActualWeightKg: 4, billableWeightKg: 4 });
});

